import 'dotenv/config';
import { Client, GatewayIntentBits, InteractionType } from 'discord.js';

const client = new Client({
  intents: [GatewayIntentBits.Guilds]
});

const allowedRoleId = process.env.ALLOWED_ROLE_ID;
const apiUrl = `http://localhost:${process.env.PORT || 3001}`;

const getGuildMemberCount = async () => {
  try {
    const guild = await client.guilds.fetch(process.env.GUILD_ID);
    return guild.memberCount ?? 0;
  } catch (error) {
    console.error('Failed to fetch guild member count:', error);
    return 0;
  }
};

const syncMemberCount = async () => {
  const count = await getGuildMemberCount();

  try {
    await fetch(`${apiUrl}/api/member-count`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.API_KEY || 'change-me'
      },
      body: JSON.stringify({ memberCount: count, updatedAt: new Date().toISOString() })
    });
  } catch (error) {
    console.error('Failed to sync member count:', error);
  }
};

client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
  syncMemberCount();
  setInterval(syncMemberCount, 30000);
});

client.on('interactionCreate', async (interaction) => {
  if (interaction.type !== InteractionType.ApplicationCommand) return;

  if (interaction.commandName !== 'update') return;

  const member = interaction.member;
  const hasPermission = !allowedRoleId || member?.roles?.cache?.has(allowedRoleId) || interaction.user.id === process.env.OWNER_ID;

  if (!hasPermission) {
    await interaction.reply({
      content: '❌ You do not have permission to use this command.',
      ephemeral: true
    });
    return;
  }

  const newEvent = interaction.options.getString('new_event', true);
  const title = interaction.options.getString('title', true);
  const body = interaction.options.getString('body', true);
  const poster = interaction.options.getString('poster', true);

  const payload = {
    newEvent,
    title,
    body,
    poster,
    submittedBy: interaction.user.tag,
    submittedAt: new Date().toISOString()
  };

  try {
    const response = await fetch(`${apiUrl}/api/update`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.API_KEY || 'change-me'
      },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new Error('Failed to save update');
    }

    await interaction.reply({
      content: `✅ Update submitted for **${newEvent}**`,
      ephemeral: true
    });
  } catch (error) {
    console.error(error);
    await interaction.reply({
      content: '❌ Failed to submit the update. Check the bot logs.',
      ephemeral: true
    });
  }
});

client.login(process.env.DISCORD_TOKEN);

