edits.text:
:root {
  --bg-deep: #090909;
  --bg-mid: #1a0d0d;
  --panel: rgba(20, 15, 15, 0.72);
  --panel-strong: rgba(15, 9, 9, 0.92);
  --line: rgba(255, 255, 255, 0.08);
  --line-soft: rgba(239, 68, 68, 0.25);
  --text: #ffffff;
  --muted: rgba(255, 240, 240, 0.78);
  --primary: #ef4444;
  --primary-strong: #dc2626;
  --secondary: #fecaca;
  --accent: #fca5a5;
  --green: #f87171;
  --shadow: 0 26px 80px rgba(0, 0, 0, 0.56);
  --radius: 26px;
  --card-soft: rgba(255, 255, 255, 0.03);
  --header-bg: rgba(18, 9, 9, 0.78);
  --surface: rgba(22, 10, 10, 0.9);
  --pill-bg: rgba(239, 68, 68, 0.08);
  --pill-border: rgba(239, 68, 68, 0.26);
  --soft-white: rgba(255, 255, 255, 0.06);
  --bg-glow-one: rgba(239, 68, 68, 0.18);
  --bg-glow-two: rgba(255, 255, 255, 0.06);
  --intro-panel-glow: rgba(239, 68, 68, 0.14);
}

body[data-theme="light"] {
  --bg-deep: #edf8ff;
  --bg-mid: #d7ebff;
  --panel: rgba(255, 255, 255, 0.9);
  --panel-strong: rgba(255, 255, 255, 0.97);
  --line: rgba(15, 23, 42, 0.12);
  --line-soft: rgba(14, 165, 233, 0.2);
  --text: #07131d;
  --muted: rgba(15, 23, 42, 0.72);
  --primary: #0ea5e9;
  --primary-strong: #2563eb;
  --secondary: #38bdf8;
  --accent: #67e8f9;
  --green: #0b8ec6;
  --shadow: 0 24px 52px rgba(14, 109, 178, 0.12);
  --card-soft: rgba(14, 165, 233, 0.04);
  --header-bg: rgba(255, 255, 255, 0.82);
  --surface: rgba(255, 255, 255, 0.95);
  --pill-bg: rgba(14, 165, 233, 0.08);
  --pill-border: rgba(37, 99, 235, 0.18);
  --soft-white: rgba(255, 255, 255, 0.7);
  --bg-glow-one: rgba(14, 165, 233, 0.18);
  --bg-glow-two: rgba(102, 167, 255, 0.14);
  --intro-panel-glow: rgba(14, 165, 233, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  position: relative;
  margin: 0;
  min-height: 100vh;
  font-family: "Inter", sans-serif;
  background:
    radial-gradient(circle at top left, var(--bg-glow-one), transparent 18%),
    radial-gradient(circle at bottom right, var(--bg-glow-two), transparent 22%),
    linear-gradient(135deg, var(--bg-deep) 0%, var(--bg-mid) 38%, var(--bg-deep) 100%);
  color: var(--text);
  overflow-x: hidden;
  transition: background 0.45s ease, color 0.45s ease, box-shadow 0.45s ease, border-color 0.45s ease;
}

* {
  transition: background-color 0.35s ease, border-color 0.35s ease, color 0.35s ease, box-shadow 0.35s ease, fill 0.35s ease, stroke 0.35s ease;
}

img {
  display: block;
  max-width: 100%;
}

button,
a {
  font: inherit;
}

button {
  border: none;
}

body[data-theme="light"] .bg-grid {
  opacity: 0.7;
}

body:not(.intro-complete) .site-header,
body:not(.intro-complete) main,
body:not(.intro-complete) .site-footer {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px);
}

body.intro-complete .site-header,
body.intro-complete main,
body.intro-complete .site-footer {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

body:not(.intro-complete) .scroll-top,
body .scroll-top.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px) scale(0.85);
}

body.intro-complete .scroll-top {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

body .site-header,
body main,
body .site-footer,
body .scroll-top {
  transition: opacity 0.7s ease, visibility 0.7s ease, transform 0.7s ease;
}

.page-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.bg-grid {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.035));
  background-size: 58px 58px;
  mask-image: radial-gradient(circle at center, black 35%, transparent 96%);
}

.bg-blur {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.8;
}

.blur-one {
  width: 26rem;
  height: 26rem;
  left: 3%;
  top: 8%;
  background: var(--bg-glow-one);
  animation: drift 18s ease-in-out infinite alternate;
}

.blur-two {
  width: 30rem;
  height: 30rem;
  right: 6%;
  bottom: 10%;
  background: var(--bg-glow-two);
  animation: drift 20s ease-in-out infinite alternate-reverse;
}

.site-header,
main,
.site-footer {
  position: relative;
  z-index: 1;
}

.intro-overlay {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, rgba(11, 8, 8, 0.96), rgba(26, 18, 18, 0.94));
