}

.theme-choice-btn[data-mode="light"] {
  background: linear-gradient(135deg, #f0fbff, #d7f0ff);
  color: #072334;
  border-color: rgba(13, 148, 136, 0.25);
  box-shadow: 0 16px 30px rgba(14, 165, 233, 0.18);
}

.theme-choice-btn[data-mode="dark"] {
