  const isMobile = window.matchMedia('(max-width: 640px)').matches;

  if (isMobile) {
    animateNumber({
      element: document.getElementById('memberCount'),
      start: 4000,
      end: 4644,
      duration: 1500,
      format: (value) => `${value.toLocaleString('en-US')}+`,
