  --bg-glow-one: rgba(239, 68, 68, 0.18);
  --bg-glow-two: rgba(255, 255, 255, 0.06);
  --intro-panel-glow: rgba(239, 68, 68, 0.14);
}

body[data-theme="light"] {
  --bg-deep: #edf8ff;
  --bg-mid: #d7ebff;
  --panel: rgba(255, 255, 255, 0.9);
  --panel-strong: rgba(255, 255, 255, 0.97);
  --line: rgba(15, 23, 42, 0.12);
  --line-soft: rgba(14, 165, 233, 0.2);
  --text: #07131d;
  --muted: rgba(15, 23, 42, 0.72);
  --primary: #0ea5e9;
  --primary-strong: #2563eb;
  --secondary: #38bdf8;
  --accent: #67e8f9;
  --green: #0b8ec6;
  --shadow: 0 24px 52px rgba(14, 109, 178, 0.12);
  --card-soft: rgba(14, 165, 233, 0.04);
  --header-bg: rgba(255, 255, 255, 0.82);
  --surface: rgba(255, 255, 255, 0.95);
  --pill-bg: rgba(14, 165, 233, 0.08);
  --pill-border: rgba(37, 99, 235, 0.18);
  --soft-white: rgba(255, 255, 255, 0.7);
  --bg-glow-one: rgba(14, 165, 233, 0.18);
  --bg-glow-two: rgba(102, 167, 255, 0.14);
  --intro-panel-glow: rgba(14, 165, 233, 0.12);
}

* {
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  position: relative;
  margin: 0;
  min-height: 100vh;
  font-family: "Inter", sans-serif;
  background:
    radial-gradient(circle at top left, var(--bg-glow-one), transparent 18%),
    radial-gradient(circle at bottom right, var(--bg-glow-two), transparent 22%),
    linear-gradient(135deg, var(--bg-deep) 0%, var(--bg-mid) 38%, var(--bg-deep) 100%);
  color: var(--text);
  overflow-x: hidden;
  transition: background 0.45s ease, color 0.45s ease, box-shadow 0.45s ease, border-color 0.45s ease;
}

* {
  transition: background-color 0.35s ease, border-color 0.35s ease, color 0.35s ease, box-shadow 0.35s ease, fill 0.35s ease, stroke 0.35s ease;
}

img {
  display: block;
  max-width: 100%;
}

button,
a {
  font: inherit;
}

button {
  border: none;
}

body[data-theme="light"] .bg-grid {
  opacity: 0.7;
}

body:not(.intro-complete) .site-header,
body:not(.intro-complete) main,
body:not(.intro-complete) .site-footer {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px);
}

body.intro-complete .site-header,
body.intro-complete main,
body.intro-complete .site-footer {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
  transform: translateY(0);
}

body:not(.intro-complete) .scroll-top,
body .scroll-top.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px) scale(0.85);
}

body.intro-complete .scroll-top {
  opacity: 1;
  visibility: visible;
  pointer-events: auto;
}

body .site-header,
body main,
body .site-footer,
body .scroll-top {
  transition: opacity 0.7s ease, visibility 0.7s ease, transform 0.7s ease;
}

.page-bg {
  position: fixed;
  inset: 0;
  pointer-events: none;
  z-index: 0;
  overflow: hidden;
}

.bg-grid {
  position: absolute;
  inset: 0;
  background-image: linear-gradient(rgba(255, 255, 255, 0.035), rgba(255, 255, 255, 0.035));
  background-size: 58px 58px;
  mask-image: radial-gradient(circle at center, black 35%, transparent 96%);
}

.bg-blur {
  position: absolute;
  border-radius: 50%;
  filter: blur(90px);
  opacity: 0.8;
}

.blur-one {
  width: 26rem;
  height: 26rem;
  left: 3%;
  top: 8%;
  background: var(--bg-glow-one);
  animation: drift 18s ease-in-out infinite alternate;
}

.blur-two {
  width: 30rem;
  height: 30rem;
  right: 6%;
  bottom: 10%;
  background: var(--bg-glow-two);
  animation: drift 20s ease-in-out infinite alternate-reverse;
}

.site-header,
main,
.site-footer {
  position: relative;
  z-index: 1;
}

.intro-overlay {
  position: fixed;
  inset: 0;
  z-index: 120;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, rgba(11, 8, 8, 0.96), rgba(26, 18, 18, 0.94));
  transition: opacity 0.7s ease, visibility 0.7s ease;
}

body[data-theme="light"] .intro-overlay {
  background: linear-gradient(135deg, rgba(247, 243, 241, 0.96), rgba(242, 231, 227, 0.94));
}

.intro-overlay.is-hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
}

.intro-panels {
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 0%, var(--intro-panel-glow) 45%, rgba(125, 211, 252, 0.1) 100%);
  animation: panelSweep 1.8s ease forwards;
}

@keyframes panelSweep {
  0% { transform: scaleX(0.1); opacity: 0; }
  100% { transform: scaleX(1); opacity: 1; }
}

.intro-content {
  position: relative;
  z-index: 1;
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 18px;
  text-align: center;
  opacity: 0;
  transform: translateY(16px) scale(0.96);
  animation: introReveal 1s ease 0.4s forwards;
}

@keyframes introReveal {
  0% { opacity: 0; transform: translateY(16px) scale(0.96); }
  100% { opacity: 1; transform: translateY(0) scale(1); }
}

.intro-logo {
  width: 88px;
  height: 88px;
  border-radius: 26px;
  object-fit: cover;
  box-shadow: 0 24px 60px rgba(216, 27, 44, 0.18);
  animation: logoPop 0.9s ease 0.65s both;
}

@keyframes logoPop {
  0% { opacity: 0; transform: scale(0.5) rotate(-6deg); }
  80% { opacity: 1; transform: scale(1.06) rotate(2deg); }
  100% { opacity: 1; transform: scale(1) rotate(0deg); }
}

.intro-copy {
  display: grid;
  gap: 8px;
}

.intro-kicker {
  color: var(--primary);
  letter-spacing: 0.22em;
  text-transform: uppercase;
  font-size: 0.72rem;
  font-weight: 700;
}

.intro-title {
  position: relative;
  display: inline-block;
  margin: 0;
  opacity: 0;
  transform: translateY(10px);
  animation: introTextFade 0.9s ease 0.7s forwards;
}

@keyframes introTextFade {
  0% { opacity: 0; transform: translateY(10px); }
  100% { opacity: 1; transform: translateY(0); }
}

.hero-typewriter {
  display: inline-block;
  white-space: nowrap;
  overflow: hidden;
}

.intro-subtitle {
  margin: 0;
  color: var(--muted);
  font-size: 1rem;
  letter-spacing: 0.02em;
}

.intro-cta {
  position: relative;
  margin-top: 18px;
  padding: 1rem 1.7rem;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  font-weight: 800;
  letter-spacing: 0.04em;
  cursor: pointer;
  box-shadow: 0 18px 44px rgba(220, 38, 38, 0.24);
  opacity: 0;
  transform: translateY(12px) scale(0.94);
  animation: introButton 0.7s ease 2s forwards;
  overflow: hidden;
}

.intro-cta::before {
  content: "";
  position: absolute;
  inset: 0;
  background: linear-gradient(120deg, transparent 0%, rgba(255,255,255,0.35) 50%, transparent 100%);
  transform: translateX(-120%);
  transition: transform 0.7s ease;
}

.intro-cta:hover::before {
  transform: translateX(120%);
}

.intro-mode-picker {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 12px;
  flex-wrap: wrap;
  margin-top: 6px;
}

.theme-choice-btn {
  min-width: 170px;
  padding: 0.9rem 1.2rem;
  border-radius: 16px;
  border: 1px solid transparent;
  cursor: pointer;
  font-weight: 700;
  letter-spacing: 0.02em;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease, filter 0.2s ease;
}

.theme-choice-btn:hover {
  transform: translateY(-2px);
}

.theme-choice-btn[data-mode="light"] {
  background: linear-gradient(135deg, #f0fbff, #d7f0ff);
  color: #072334;
  border-color: rgba(13, 148, 136, 0.25);
  box-shadow: 0 16px 30px rgba(14, 165, 233, 0.18);
}

.theme-choice-btn[data-mode="dark"] {
  background: linear-gradient(135deg, #1b1d20, #07090b);
  color: #fff;
  border-color: rgba(239, 68, 68, 0.28);
  box-shadow: 0 16px 30px rgba(239, 68, 68, 0.18);
}

.theme-choice-btn.is-selected {
  box-shadow: 0 0 0 2px rgba(255, 255, 255, 0.18), 0 18px 30px rgba(0, 0, 0, 0.18);
  filter: saturate(1.12);
}

.theme-choice-btn[data-mode="light"].is-selected {
  border-color: rgba(37, 99, 235, 0.45);
}

.theme-choice-btn[data-mode="dark"].is-selected {
  border-color: rgba(239, 68, 68, 0.5);
}


@keyframes introButton {
  to { opacity: 1; transform: translateY(0) scale(1); }
}

.site-header {
  position: unset;
  top: 0;
  width: min(1200px, calc(100% - 32px));
  margin: 18px auto 0;
  padding: 14px 18px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border: 1px solid var(--line);
  background: var(--header-bg);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  border-radius: 24px;
  box-shadow: var(--shadow);
  transition: transform 0.35s ease, opacity 0.35s ease, background 0.35s ease;
}

.site-header.is-hidden {
  transform: translateY(-120%);
  opacity: 0;
}

.brand-wrap {
  display: flex;
  align-items: center;
  gap: 12px;
}

.brand-logo {
  width: 42px;
  height: 42px;
  object-fit: cover;
  border-radius: 14px;
}

.small-logo {
  width: 30px;
  height: 30px;
}

.brand-name {
  font-size: 0.86rem;
  letter-spacing: 0.08em;
  font-weight: 800;
  text-transform: uppercase;
  color: var(--text);
}

.header-tools {
  display: flex;
  align-items: center;
  gap: 12px;
}

.theme-toggle {
  width: 52px;
  height: 52px;
  border-radius: 16px;
  display: grid;
  place-items: center;
  background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(255,255,255,0.02));
  border: 1px solid var(--line-soft);
  color: var(--text);
  cursor: pointer;
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.08), 0 10px 20px rgba(15, 23, 42, 0.12);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease, background 0.2s ease;
}

.theme-toggle:hover {
  transform: translateY(-2px) scale(1.02);
  border-color: rgba(25, 183, 255, 0.6);
  box-shadow: inset 0 1px 0 rgba(255,255,255,0.12), 0 14px 24px rgba(14, 165, 233, 0.15);
}

.theme-toggle__icon {
  display: inline-flex;
  width: 22px;
  height: 22px;
  align-items: center;
  justify-content: center;
  transform: rotate(0deg);
  transition: transform 0.35s ease;
}

.theme-toggle:hover .theme-toggle__icon {
  transform: rotate(14deg) scale(1.06);
}

.theme-toggle__icon svg {
  width: 22px;
  height: 22px;
  stroke: currentColor;
  fill: none;
  stroke-width: 1.8;
  stroke-linecap: round;
  stroke-linejoin: round;
}

body[data-theme="dark"] .theme-toggle {
  background: linear-gradient(180deg, rgba(255,255,255,0.06), rgba(239,68,68,0.08));
}

body[data-theme="light"] .theme-toggle {
  background: linear-gradient(180deg, rgba(255,255,255,0.8), rgba(186,230,253,0.22));
}

body[data-theme="light"] .theme-toggle__icon svg {
  fill: currentColor;
  stroke: currentColor;
}

.top-nav {
  display: flex;
  align-items: center;
  gap: 1.4rem;
}

.top-nav a {
  color: var(--muted);
  text-decoration: none;
  font-size: 0.9rem;
  transition: color 0.2s ease, transform 0.2s ease;
}

.top-nav a:hover {
  color: var(--text);
  transform: translateY(-1px);
}

.menu-toggle {
  display: none;
  width: 56px;
  height: 56px;
  border: 1px solid var(--line-soft);
  border-radius: 18px;
  background: var(--card-soft);
  align-items: center;
  justify-content: center;
  flex-direction: column;
  gap: 6px;
  cursor: pointer;
  color: var(--text);
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.menu-toggle span {
  width: 22px;
  height: 2px;
  border-radius: 999px;
  background: currentColor;
  display: block;
  transition: transform 0.25s ease, opacity 0.25s ease;
}

.menu-toggle:hover {
  transform: translateY(-1px);
  border-color: rgba(25, 183, 255, 0.6);
  box-shadow: 0 12px 22px rgba(25, 183, 255, 0.12);
}

.menu-toggle[aria-expanded="true"] span:nth-child(1) {
  transform: translateY(8px) rotate(45deg);
}

.menu-toggle[aria-expanded="true"] span:nth-child(2) {
  opacity: 0;
}

.menu-toggle[aria-expanded="true"] span:nth-child(3) {
  transform: translateY(-8px) rotate(-45deg);
}

.menu-overlay {
  position: fixed;
  inset: 0;
  background: rgba(6, 5, 5, 0.68);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s ease;
  z-index: 20;
}

.menu-overlay.open {
  opacity: 1;
  visibility: visible;
}

.menu-panel {
  width: min(540px, calc(100% - 26px));
  padding: 24px 20px 20px;
  border: 1px solid var(--line);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(20, 15, 15, 0.94), rgba(10, 9, 9, 0.96));
  box-shadow: var(--shadow);
  transform: translateY(18px) scale(0.97);
  transition: transform 0.35s ease;
}

body[data-theme="light"] .menu-panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(248, 243, 240, 0.98));
}

.menu-overlay.open .menu-panel {
  transform: translateY(0) scale(1);
}

.menu-header {
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.panel-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.panel-kicker {
  margin: 0 0 6px;
  color: var(--muted);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-size: 0.66rem;
}

.panel-brand h2 {
  margin: 0;
  font-size: clamp(1.2rem, 3vw, 1.8rem);
}

.menu-links {
  display: grid;
  gap: 10px;
  margin-top: 20px;
}

.menu-links a {
  padding: 16px 18px;
  border-radius: 18px;
  color: var(--text);
  text-decoration: none;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid transparent;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.menu-links a:hover {
  transform: translateX(4px);
  border-color: rgba(255, 61, 77, 0.3);
  background: rgba(216, 27, 44, 0.08);
}

.auth-card {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.discord-user {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
  padding: 12px 14px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.discord-user img {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.12);
}

.discord-user-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.discord-user-text strong {
  font-size: 1rem;
}

.discord-user-text small {
  color: var(--muted);
}

.discord-button {
  width: 100%;
  border: none;
  border-radius: 16px;
  padding: 14px 18px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.discord-button:hover {
  transform: translateY(-2px);
}

.discord-button.primary {
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  box-shadow: 0 18px 40px rgba(216, 27, 44, 0.25);
}

.discord-button.secondary {
  margin-top: 12px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.hidden {
  display: none !important;
}

.section-shell {
  width: min(1200px, calc(100% - 32px));
  margin: 0 auto;
  padding: 88px 0;
}

.hero {
  display: grid;
  grid-template-columns: 1.12fr 0.88fr;
  align-items: center;
  min-height: calc(100vh - 140px);
  gap: 56px;
  padding-top: 30px;
}

.hero-copy {
  max-width: 620px;
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-radius: 999px;
  border: 1px solid rgba(34, 197, 94, 0.28);
  background: rgba(16, 185, 129, 0.08);
  color: var(--text);
  font-size: 0.76rem;
  box-shadow: 0 0 28px rgba(16, 185, 129, 0.12);
}

#memberCount {
  color: #34d399;
  font-weight: 800;
  letter-spacing: -0.03em;
  text-shadow: 0 0 16px rgba(52, 211, 153, 0.28);
  animation: countBreath 1.8s ease-in-out infinite;
}

.live-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 18px rgba(52, 211, 153, 0.9), 0 0 34px rgba(52, 211, 153, 0.42);
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes countBreath {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.06); opacity: 0.92; }
}

.hero h1 {
  margin: 24px 0 0;
  font-size: clamp(3.3rem, 6vw, 6.4rem);
  letter-spacing: -0.09em;
  line-height: 0.9;
  color: var(--text);
  white-space: normal;
  overflow: visible;
  width: auto;
  max-width: 100%;
}

.hero-typewriter {
  width: auto;
  max-width: 100%;
  border-right-color: rgba(216, 27, 44, 0.9);
  display: inline-block;
  white-space: normal;
  overflow: visible;
  word-break: keep-all;
}

.subtext {
  margin-top: 22px;
  max-width: 570px;
  color: var(--muted);
  font-size: 1.08rem;
  line-height: 1.8;
}

.hero-actions {
  margin-top: 30px;
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.primary-cta,
.secondary-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  padding: 0 26px;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  transition: transform 0.22s cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 0.22s ease, border-color 0.22s ease, filter 0.22s ease;
}

.primary-cta {
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  box-shadow: 0 20px 44px rgba(216, 27, 44, 0.24);
}

.primary-cta:hover,
.secondary-cta:hover {
  filter: saturate(1.06);
  box-shadow: 0 24px 52px rgba(216, 27, 44, 0.18);
}

.primary-cta:hover,
.secondary-cta:hover,
.view-more-btn:hover,
.gallery-arrow:hover,
.featured-arrow:hover {
  transform: translateY(-2px);
}

.secondary-cta {
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}

.hero-badges span {
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
  font-size: 0.74rem;
}

.hero-visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 540px;
  width: min(500px, 100%);
  margin-left: auto;
}

.glass-panel {
  background: linear-gradient(180deg, rgba(20, 16, 16, 0.8), rgba(12, 10, 10, 0.7));
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.28);
}

body[data-theme="light"] .glass-panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(251, 247, 245, 0.8));
  border-color: rgba(86, 42, 42, 0.08);
}

.visual-card {
  position: relative;
  width: min(470px, 100%);
  padding: 24px;
  border-radius: 30px;
}

.main-card {
  min-height: 290px;
  transform: rotate(-8deg) translateY(10px);
}

.floating-card {
  position: absolute;
  right: 18px;
  bottom: 34px;
  width: min(290px, 66%);
  padding: 22px;
  transform: rotate(8deg);
  animation: floatCard 6s ease-in-out infinite alternate;
}

.current-event-card {
  cursor: pointer;
  overflow: hidden;
}

.current-event-card:focus-visible {
  outline: 2px solid #34d399;
  outline-offset: 4px;
}

.current-event-body {
  display: -webkit-box;
  margin-top: 9px !important;
  overflow: hidden;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
