  box-shadow: 0 24px 52px rgba(216, 27, 44, 0.18);
}

.primary-cta:hover,
.secondary-cta:hover,
.view-more-btn:hover,
.gallery-arrow:hover,
.featured-arrow:hover {
  transform: translateY(-2px);
}

.secondary-cta {
