  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}

.hero-badges span {
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
  font-size: 0.74rem;
}

.hero-visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 540px;
  width: min(500px, 100%);
  margin-left: auto;
}

.glass-panel {
  background: linear-gradient(180deg, rgba(20, 16, 16, 0.8), rgba(12, 10, 10, 0.7));
  border: 1px solid rgba(255, 255, 255, 0.08);
