  bottom: 34px;
  width: min(290px, 66%);
  padding: 22px;
  transform: rotate(8deg);
  animation: floatCard 6s ease-in-out infinite alternate;
}

.current-event-card {
  cursor: pointer;
  overflow: hidden;
}

.current-event-card:focus-visible {
  outline: 2px solid #34d399;
  outline-offset: 4px;
}

.current-event-card h3 {
  max-width: 92%;
  font-size: clamp(1.8rem, 4vw, 2.45rem);
  line-height: 1;
}

.current-event-body {
  display: -webkit-box;
  margin-top: 9px !important;
  overflow: hidden;
  color: var(--muted);
  font-size: 0.76rem;
  line-height: 1.45;
  -webkit-box-orient: vertical;
  -webkit-line-clamp: 2;
}

.current-event-details {
  display: flex;
  flex-direction: column;
  gap: 4px;
  margin-top: 12px;
  color: var(--muted);
  font-size: 0.72rem;
}

.current-event-poster {
  position: absolute;
  right: 12px;
  bottom: 12px;
  width: 108px;
  height: 132px;
  object-fit: cover;
  border: 2px solid rgba(52, 211, 153, 0.65);
  border-radius: 14px;
  opacity: 0;
  transform: translateY(18px) rotate(-5deg) scale(0.82);
  pointer-events: none;
  transition: opacity 0.35s ease, transform 0.35s cubic-bezier(0.22, 1, 0.36, 1);
}

.current-event-card:hover .current-event-poster.is-visible,
.current-event-card:focus-visible .current-event-poster.is-visible {
