}

.floating-card p {
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.floating-card h3 {
  margin-top: 10px;
  font-size: 1.5rem;
  color: var(--text);
}

.progress-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 18px;
  color: var(--muted);
  font-size: 0.8rem;
}

.progress-bar {
  position: relative;
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
  margin-top: 12px;
}

.progress-bar span {
  position: absolute;
  inset: 0 auto 0 0;
