import 'dotenv/config';
import { REST, Routes, ApplicationCommandOptionType } from 'discord.js';

const commands = [
  {
    name: 'update',
    description: 'Submit a new community update',
    options: [
      {
        name: 'current_event',
        description: 'Update the current event card title and progress',
        type: ApplicationCommandOptionType.Subcommand,
        options: [
          {
            name: 'title',
            description: 'Current event card title',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'progress',
            description: 'Completion percentage from 0 to 100',
            type: ApplicationCommandOptionType.Integer,
            required: true,
            min_value: 0,
            max_value: 100
          }
        ]
      },
      {
        name: 'announcement',
        description: 'Submit a new community update',
        type: ApplicationCommandOptionType.Subcommand,
        options: [
          {
            name: 'new_event',
            description: 'Name of the event or update',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'title',
            description: 'Update title',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'body',
            description: 'Detailed update body',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'date',
            description: 'Event date',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'time',
            description: 'Event time and timezone',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'invite_link',
            description: 'Discord invite link for the Join button',
            type: ApplicationCommandOptionType.String,
            required: true
          },
          {
            name: 'poster',
            description: 'Optional event poster image upload',
            type: ApplicationCommandOptionType.Attachment,
            required: false
          }
        ]
      }
    ]
  }
];

const rest = new REST({ version: '10' }).setToken(process.env.DISCORD_TOKEN);

try {
  await rest.put(
    Routes.applicationGuildCommands(process.env.CLIENT_ID, process.env.GUILD_ID),
    { body: commands }
  );

  console.log('Slash commands registered successfully');
} catch (error) {
  console.error('Failed to register slash commands:', error);
}

import 'dotenv/config';
import { Client, GatewayIntentBits, InteractionType } from 'discord.js';

const client = new Client({
  intents: [GatewayIntentBits.Guilds]
});

const allowedRoleId = process.env.ALLOWED_ROLE_ID;
const apiUrl = `http://localhost:${process.env.PORT || 3001}`;

const getGuildMemberCount = async () => {
  try {
    const guild = await client.guilds.fetch(process.env.GUILD_ID);
    return guild.memberCount ?? 0;
  } catch (error) {
    console.error('Failed to fetch guild member count:', error);
    return 0;
  }
};

const syncMemberCount = async () => {
  const count = await getGuildMemberCount();

  try {
    await fetch(`${apiUrl}/api/member-count`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.API_KEY || 'change-me'
      },
      body: JSON.stringify({ memberCount: count, updatedAt: new Date().toISOString() })
    });
  } catch (error) {
    console.error('Failed to sync member count:', error);
  }
};

client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
  syncMemberCount();
  setInterval(syncMemberCount, 30000);
});

client.on('interactionCreate', async (interaction) => {
  if (interaction.type !== InteractionType.ApplicationCommand) return;

  if (interaction.commandName !== 'update') return;

  const member = interaction.member;
  const hasPermission = !allowedRoleId || member?.roles?.cache?.has(allowedRoleId) || interaction.user.id === process.env.OWNER_ID;

  if (!hasPermission) {
    await interaction.reply({
      content: '❌ You do not have permission to use this command.',
      ephemeral: true
    });
    return;
  }

  const subcommand = interaction.options.getSubcommand();

  if (subcommand === 'current_event') {
    const title = interaction.options.getString('title', true);
    const progress = interaction.options.getInteger('progress', true);

    try {
      const response = await fetch(`${apiUrl}/api/current-event`, {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'x-api-key': process.env.API_KEY || 'change-me'
        },
        body: JSON.stringify({ title, progress, updatedAt: new Date().toISOString() })
      });

      if (!response.ok) throw new Error('Failed to save current event');

      await interaction.reply({
        content: `✅ Current event updated: **${title}** (${progress}%)`,
        ephemeral: true
      });
    } catch (error) {
      console.error(error);
      await interaction.reply({
        content: '❌ Failed to update the current event card. Check the bot logs.',
        ephemeral: true
      });
    }
    return;
  }

  const newEvent = interaction.options.getString('new_event', true);
  const title = interaction.options.getString('title', true);
  const body = interaction.options.getString('body', true);
  const date = interaction.options.getString('date', true);
  const time = interaction.options.getString('time', true);
  const inviteLink = interaction.options.getString('invite_link', true);
  const poster = interaction.options.getAttachment('poster');

  const payload = {
    newEvent,
    title,
    body,
    date,
    time,
    inviteLink,
    poster: poster?.url || null,
    submittedBy: interaction.user.tag,
    submittedAt: new Date().toISOString()
  };

  try {
    const response = await fetch(`${apiUrl}/api/update`, {
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'x-api-key': process.env.API_KEY || 'change-me'
      },
      body: JSON.stringify(payload)
    });

    if (!response.ok) {
      throw new Error('Failed to save update');
    }

    await interaction.reply({
      content: `✅ Update submitted for **${newEvent}**`,
      ephemeral: true
    });
  } catch (error) {
    console.error(error);
    await interaction.reply({
      content: '❌ Failed to submit the update. Check the bot logs.',
      ephemeral: true
    });
  }
});

client.login(process.env.DISCORD_TOKEN);

import 'dotenv/config';
import express from 'express';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const app = express();
const port = Number(process.env.PORT || 3001);
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const dataFile = path.join(__dirname, 'updates.json');
const memberFile = path.join(__dirname, 'member-count.json');
const currentEventFile = path.join(__dirname, 'current-event.json');

app.use(express.json({ limit: '5mb' }));

app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);

  if (!origin || allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin || '*');
    res.header('Access-Control-Allow-Headers', 'Content-Type, x-api-key');
    res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  }

  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

const readJson = async (file) => {
  try {
    const raw = await fs.readFile(file, 'utf8');
    return JSON.parse(raw);
  } catch {
    return [];
  }
};

const writeJson = async (file, data) => {
  await fs.writeFile(file, JSON.stringify(data, null, 2));
};

const getMemberCount = async () => {
  try {
    const raw = await fs.readFile(memberFile, 'utf8');
    const payload = JSON.parse(raw);
    return Number(payload.memberCount || 0);
  } catch {
    return 0;
