const createDots = (container, total, onSelect) => {
  if (!container) return;

  container.innerHTML = '';

  for (let i = 0; i < total; i += 1) {
    const dot = document.createElement('button');
    dot.type = 'button';
    dot.className = 'carousel-dot';
