  bottom: 34px;
  width: min(290px, 66%);
  padding: 22px;
  transform: rotate(8deg);
  animation: floatCard 6s ease-in-out infinite alternate;
}

.card-topline {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.dot {
