  border-radius: 30px;
  touch-action: pan-y;
  cursor: grab;
}

.featured-viewport:active {
  cursor: grabbing;
}

.featured-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.featured-slide {
  min-width: 100%;
