  padding: 18px;
  border-radius: 30px;
}

.gallery-stage {
  overflow: hidden;
  border-radius: 24px;
  touch-action: pan-y;
  cursor: grab;
}

.gallery-stage:active {
  cursor: grabbing;
}

.gallery-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.gallery-slide {
