}

.latest-update-label {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #a7f3d0;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.latest-update-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.55), 0 0 16px rgba(52, 211, 153, 0.9);
