      <path d="M12 1.8v2.2M12 20v2.2M4.9 4.9l1.6 1.6M17.5 17.5l1.6 1.6M1.8 12h2.2M20 12h2.2M4.9 19.1l1.6-1.6M17.5 6.5l1.6-1.6"/>
    </g>
  </svg>
`;

const moonIcon = `
  <svg viewBox="0 0 24 24" aria-hidden="true">
