  position: fixed;
  inset: 0;
  background: rgba(6, 5, 5, 0.68);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  display: flex;
  justify-content: center;
  align-items: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.35s ease, visibility 0.35s ease;
  z-index: 20;
}

.menu-overlay.open {
  opacity: 1;
  visibility: visible;
}

.menu-panel {
  width: min(540px, calc(100% - 26px));
  padding: 24px 20px 20px;
  border: 1px solid var(--line);
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(20, 15, 15, 0.94), rgba(10, 9, 9, 0.96));
  box-shadow: var(--shadow);
  transform: translateY(18px) scale(0.97);
  transition: transform 0.35s ease;
}

body[data-theme="light"] .menu-panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.97), rgba(248, 243, 240, 0.98));
}

.menu-overlay.open .menu-panel {
  transform: translateY(0) scale(1);
}

.menu-header {
  padding-bottom: 18px;
  border-bottom: 1px solid rgba(255, 255, 255, 0.08);
}

.panel-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.panel-kicker {
  margin: 0 0 6px;
  color: var(--muted);
  letter-spacing: 0.2em;
  text-transform: uppercase;
  font-size: 0.66rem;
}

.panel-brand h2 {
  margin: 0;
  font-size: clamp(1.2rem, 3vw, 1.8rem);
}

.menu-links {
  display: grid;
  gap: 10px;
  margin-top: 20px;
}

.menu-links a {
  padding: 16px 18px;
  border-radius: 18px;
  color: var(--text);
  text-decoration: none;
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid transparent;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.menu-links a:hover {
  transform: translateX(4px);
  border-color: rgba(255, 61, 77, 0.3);
  background: rgba(216, 27, 44, 0.08);
}

.auth-card {
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid rgba(255, 255, 255, 0.08);
}

.discord-user {
  display: flex;
  align-items: center;
  gap: 14px;
  margin-bottom: 16px;
  padding: 12px 14px;
  border-radius: 18px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
}

.discord-user img {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255, 255, 255, 0.12);
}

.discord-user-text {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.discord-user-text strong {
  font-size: 1rem;
}

.discord-user-text small {
  color: var(--muted);
}

.discord-button {
  width: 100%;
  border: none;
  border-radius: 16px;
  padding: 14px 18px;
  font-weight: 700;
  cursor: pointer;
  transition: transform 0.2s ease, box-shadow 0.2s ease;
}

.discord-button:hover {
  transform: translateY(-2px);
}

.discord-button.primary {
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  box-shadow: 0 18px 40px rgba(216, 27, 44, 0.25);
}

.discord-button.secondary {
  margin-top: 12px;
  background: rgba(255, 255, 255, 0.04);
  color: var(--text);
  border: 1px solid rgba(255, 255, 255, 0.08);
}

.hidden {
  display: none !important;
}

.section-shell {
  width: min(1200px, calc(100% - 32px));
  margin: 0 auto;
  padding: 88px 0;
}

.hero {
  display: grid;
  grid-template-columns: 1.12fr 0.88fr;
  align-items: center;
  min-height: calc(100vh - 140px);
  gap: 56px;
  padding-top: 30px;
}

.hero-copy {
  max-width: 620px;
}

.live-pill {
  display: inline-flex;
  align-items: center;
  gap: 10px;
  padding: 10px 16px;
  border-radius: 999px;
  border: 1px solid rgba(34, 197, 94, 0.28);
  background: rgba(16, 185, 129, 0.08);
  color: var(--text);
  font-size: 0.76rem;
  box-shadow: 0 0 28px rgba(16, 185, 129, 0.12);
}

#memberCount {
  color: #34d399;
  font-weight: 800;
  letter-spacing: -0.03em;
  text-shadow: 0 0 16px rgba(52, 211, 153, 0.28);
  animation: countBreath 1.8s ease-in-out infinite;
}

.live-dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 18px rgba(52, 211, 153, 0.9), 0 0 34px rgba(52, 211, 153, 0.42);
  animation: pulse 1.8s ease-in-out infinite;
}

@keyframes countBreath {
  0%, 100% { transform: scale(1); opacity: 1; }
  50% { transform: scale(1.06); opacity: 0.92; }
}

.hero h1 {
  margin: 24px 0 0;
  font-size: clamp(3.3rem, 6vw, 6.4rem);
  letter-spacing: -0.09em;
  line-height: 0.9;
  color: var(--text);
  white-space: normal;
  overflow: visible;
  width: auto;
  max-width: 100%;
}

.hero-typewriter {
  width: auto;
  max-width: 100%;
  border-right-color: rgba(216, 27, 44, 0.9);
  display: inline-block;
  white-space: normal;
  overflow: visible;
  word-break: keep-all;
}

.subtext {
  margin-top: 22px;
  max-width: 570px;
  color: var(--muted);
  font-size: 1.08rem;
  line-height: 1.8;
}

.hero-actions {
  margin-top: 30px;
  display: flex;
  flex-wrap: wrap;
  gap: 14px;
}

.primary-cta,
.secondary-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 56px;
  padding: 0 26px;
  border-radius: 999px;
  text-decoration: none;
  font-weight: 700;
  transition: transform 0.22s cubic-bezier(0.2, 0.7, 0.2, 1), box-shadow 0.22s ease, border-color 0.22s ease, filter 0.22s ease;
}

.primary-cta {
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  box-shadow: 0 20px 44px rgba(216, 27, 44, 0.24);
}

.primary-cta:hover,
.secondary-cta:hover {
  filter: saturate(1.06);
  box-shadow: 0 24px 52px rgba(216, 27, 44, 0.18);
}

.primary-cta:hover,
.secondary-cta:hover,
.view-more-btn:hover,
.gallery-arrow:hover,
.featured-arrow:hover {
  transform: translateY(-2px);
}

.secondary-cta {
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.03);
  color: var(--text);
}

.hero-badges {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 28px;
}

.hero-badges span {
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid rgba(255, 255, 255, 0.08);
  background: rgba(255, 255, 255, 0.02);
  color: var(--muted);
  font-size: 0.74rem;
}

.hero-visual {
  position: relative;
  display: grid;
  place-items: center;
  min-height: 540px;
  width: min(500px, 100%);
  margin-left: auto;
}

.glass-panel {
  background: linear-gradient(180deg, rgba(20, 16, 16, 0.8), rgba(12, 10, 10, 0.7));
  border: 1px solid rgba(255, 255, 255, 0.08);
  backdrop-filter: blur(22px);
  -webkit-backdrop-filter: blur(22px);
  box-shadow: 0 28px 80px rgba(0, 0, 0, 0.28);
}

body[data-theme="light"] .glass-panel {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.78), rgba(251, 247, 245, 0.8));
  border-color: rgba(86, 42, 42, 0.08);
}

.visual-card {
  position: relative;
  width: min(470px, 100%);
  padding: 24px;
  border-radius: 30px;
}

.main-card {
  min-height: 290px;
  transform: rotate(-8deg) translateY(10px);
}

.floating-card {
  position: absolute;
  right: 18px;
  bottom: 34px;
  width: min(290px, 66%);
  padding: 22px;
  transform: rotate(8deg);
  animation: floatCard 6s ease-in-out infinite alternate;
}

.card-topline {
  display: flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.7rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.dot {
  width: 11px;
  height: 11px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--accent), var(--primary));
  box-shadow: 0 0 20px rgba(255, 61, 77, 0.56);
}

.analytics-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 16px;
  margin-top: 28px;
}

.metric-box {
  padding: 20px 18px;
  border-radius: 20px;
  background: rgba(255, 255, 255, 0.03);
  border: 1px solid rgba(255, 255, 255, 0.05);
  min-height: 92px;
}

.metric-box strong {
  display: block;
  color: var(--text);
  font-size: clamp(1.6rem, 3vw, 2.4rem);
}

.metric-box span {
  color: var(--muted);
  font-size: 0.78rem;
}

.metric-box.accent {
  background: linear-gradient(135deg, rgba(216, 27, 44, 0.14), rgba(255, 176, 103, 0.04));
}

.metric-box.wide {
  grid-column: 1 / -1;
}

.floating-card p,
.floating-card h3,
.progress-row {
  margin: 0;
}

.floating-card p {
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.18em;
  text-transform: uppercase;
}

.floating-card h3 {
  margin-top: 10px;
  font-size: 1.5rem;
  color: var(--text);
}

.progress-row {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-top: 18px;
  color: var(--muted);
  font-size: 0.8rem;
}

.progress-bar {
  position: relative;
  width: 100%;
  height: 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.06);
  overflow: hidden;
  margin-top: 12px;
}

.progress-bar span {
  position: absolute;
  inset: 0 auto 0 0;
  width: 85%;
  border-radius: inherit;
  background: linear-gradient(90deg, var(--secondary), var(--primary));
}

.feature-showcase {
  padding-top: 38px;
}

.section-heading {
  margin-bottom: 28px;
}

.section-heading h2 {
  margin: 0;
  font-size: clamp(2.4rem, 4vw, 4rem);
  letter-spacing: -0.06em;
  color: var(--text);
}

.eyebrow {
  margin: 0 0 16px;
  color: var(--primary);
  letter-spacing: 0.18em;
  text-transform: uppercase;
  font-size: 0.7rem;
  font-weight: 700;
}

.split-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 18px;
}

.status-pill {
  padding: 10px 14px;
  border-radius: 999px;
  border: 1px solid var(--pill-border);
  background: var(--pill-bg);
  color: var(--text);
  font-size: 0.74rem;
}

.live-status-pill {
  border-color: rgba(52, 211, 153, 0.35);
  background: rgba(16, 185, 129, 0.12);
  color: #a7f3d0;
  box-shadow: 0 0 24px rgba(52, 211, 153, 0.12);
  animation: liveStatusBreath 2.4s ease-in-out infinite;
}

@keyframes liveStatusBreath {
  0%, 100% { box-shadow: 0 0 18px rgba(52, 211, 153, 0.1); }
  50% { box-shadow: 0 0 28px rgba(52, 211, 153, 0.28); }
}

.featured-carousel {
  display: grid;
  gap: 18px;
  align-items: center;
}

.featured-viewport {
  overflow: hidden;
  border-radius: 30px;
  touch-action: pan-y;
  cursor: grab;
}

.featured-viewport:active {
  cursor: grabbing;
}

.featured-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.featured-slide {
  min-width: 100%;
  display: grid;
  grid-template-columns: 1.1fr 0.9fr;
  gap: 22px;
  align-items: center;
  background: linear-gradient(180deg, rgba(20, 16, 16, 0.82), rgba(12, 10, 10, 0.78));
  border: 1px solid rgba(255, 255, 255, 0.08);
  border-radius: 30px;
  padding: 18px;
  box-shadow: 0 18px 40px rgba(0, 0, 0, 0.12);
}

body[data-theme="light"] .featured-slide {
  background: linear-gradient(180deg, rgba(255, 255, 255, 0.82), rgba(246, 239, 236, 0.86));
}

.featured-media {
  min-height: 360px;
  border-radius: 24px;
  display: flex;
  align-items: end;
  justify-content: center;
  padding: 18px;
  color: rgba(255, 255, 255, 0.88);
  text-transform: uppercase;
  letter-spacing: 0.14em;
  font-size: 0.72rem;
  border: 1px solid rgba(255,255,255,0.08);
}

.feature-media-one {
  background: linear-gradient(135deg, rgba(135, 43, 43, 0.8), rgba(60, 29, 29, 0.85));
}

.feature-media-two {
  background: linear-gradient(135deg, rgba(92, 99, 119, 0.76), rgba(28, 34, 40, 0.9));
}

.feature-media-three {
  background: linear-gradient(135deg, rgba(129, 103, 76, 0.82), rgba(55, 41, 35, 0.88));
}

.featured-copy {
  padding: 14px 10px 14px 0;
}

.small-eyebrow {
  margin-bottom: 12px;
  letter-spacing: 0.18em;
}

.featured-copy h3 {
  margin: 0;
  color: var(--text);
  font-size: clamp(2rem, 3vw, 3rem);
  letter-spacing: -0.06em;
}

.featured-copy p {
  color: var(--muted);
  line-height: 1.8;
  margin: 16px 0 0;
}

.featured-actions {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  margin-top: 26px;
}

.featured-arrow {
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: rgba(255, 255, 255, 0.04);
  border: 1px solid rgba(255, 255, 255, 0.12);
  color: var(--text);
  cursor: pointer;
  transition: transform 0.18s ease, border-color 0.18s ease, box-shadow 0.18s ease, background 0.18s ease;
  font-size: 1.4rem;
  box-shadow: 0 10px 18px rgba(0, 0, 0, 0.18);
}

.featured-arrow:hover {
  border-color: rgba(255, 61, 77, 0.42);
  background: rgba(255, 255, 255, 0.06);
  box-shadow: 0 14px 22px rgba(216, 27, 44, 0.1);
}

.study-section {
  padding-top: 28px;
}

.study-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.study-card {
  border-radius: 28px;
  overflow: hidden;
}

.study-image {
  min-height: 220px;
  display: flex;
  align-items: end;
  justify-content: center;
  padding: 18px;
  font-size: 0.72rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
  color: rgba(255,255,255,0.86);
  border-bottom: 1px solid rgba(255,255,255,0.08);
}

.study-pomodoro {
  background: linear-gradient(135deg, rgba(90, 62, 62, 0.84), rgba(35, 29, 29, 0.94));
}

.study-lofi {
  background: linear-gradient(135deg, rgba(82, 96, 104, 0.82), rgba(27, 36, 45, 0.9));
}

.study-group {
  background: linear-gradient(135deg, rgba(121, 91, 60, 0.82), rgba(46, 33, 32, 0.92));
}

.study-copy {
  padding: 20px 20px 22px;
}

.study-tag {
  display: inline-flex;
  padding: 7px 10px;
  border-radius: 999px;
  font-size: 0.7rem;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  background: rgba(216, 27, 44, 0.08);
  color: var(--primary);
}

.study-copy h3 {
  margin: 16px 0 10px;
  color: var(--text);
  font-size: 1.5rem;
}

.study-copy p {
  margin: 0;
  color: var(--muted);
  line-height: 1.8;
}

.gallery-section,
.live-section,
.team-section,
.support-section {
  padding-top: 32px;
}

.gallery-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-end;
  gap: 12px;
}

.view-more-btn {
  background: rgba(255, 255, 255, 0.02);
  border: 1px solid var(--line-soft);
  color: var(--text);
  border-radius: 999px;
  padding: 12px 18px;
  cursor: pointer;
  transition: transform 0.2s ease, border-color 0.2s ease, box-shadow 0.2s ease;
}

.view-more-btn:hover {
  border-color: rgba(255, 61, 77, 0.45);
  box-shadow: 0 12px 26px rgba(216, 27, 44, 0.08);
}

.gallery-shell {
  display: grid;
  gap: 18px;
  padding: 18px;
  border-radius: 30px;
}

.gallery-stage {
  overflow: hidden;
  border-radius: 24px;
  touch-action: pan-y;
  cursor: grab;
}

.gallery-stage:active {
  cursor: grabbing;
}

.gallery-track {
  display: flex;
  transition: transform 0.5s cubic-bezier(0.22, 1, 0.36, 1);
}

.gallery-slide {
  min-width: 100%;
  cursor: pointer;
  transition: transform 0.28s ease;
}

.gallery-slide:hover {
  transform: translateY(-8px) scale(1.01);
}

.gallery-image {
  min-height: 420px;
  display: flex;
  align-items: end;
  justify-content: center;
  padding: 22px;
  border-radius: 26px;
  border: 1px solid rgba(255,255,255,0.08);
  color: rgba(255,255,255,0.9);
  letter-spacing: 0.12em;
  text-transform: uppercase;
  font-size: 0.74rem;
  transition: transform 0.28s ease, box-shadow 0.28s ease;
}

.gallery-slide:hover .gallery-image {
  transform: scale(1.02);
  box-shadow: 0 18px 38px rgba(0, 0, 0, 0.18);
}

.gallery-image--one {
  background: linear-gradient(135deg, rgba(117, 57, 57, 0.8), rgba(48, 27, 27, 0.92));
}

.gallery-image--two {
  background: linear-gradient(135deg, rgba(120, 81, 68, 0.8), rgba(39, 31, 28, 0.9));
}

.gallery-image--three {
  background: linear-gradient(135deg, rgba(109, 90, 125, 0.82), rgba(31, 25, 39, 0.9));
}

.gallery-image--four {
  background: linear-gradient(135deg, rgba(83, 89, 102, 0.8), rgba(28, 32, 36, 0.9));
}

.gallery-arrow {
  display: none;
}

.carousel-meta {
  display: grid;
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 12px;
  padding: 0 8px;
}

.swipe-hint {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--muted);
  font-size: 0.72rem;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.9;
  animation: swipePulse 1.8s ease-in-out infinite;
  justify-self: start;
}

.swipe-hint__dot {
  width: 10px;
  height: 10px;
  border-radius: 50%;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
  box-shadow: 0 0 18px rgba(216, 27, 44, 0.38);
}

.carousel-dots {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  grid-column: 2;
  justify-self: center;
}

.carousel-dot {
  width: 9px;
  height: 9px;
  padding: 0;
  border: 0;
  border-radius: 50%;
  background: rgba(255, 255, 255, 0.18);
  cursor: pointer;
  transition: transform 0.2s ease, background 0.2s ease, opacity 0.2s ease;
}

.carousel-dot.is-active {
  width: 28px;
  border-radius: 999px;
  background: linear-gradient(135deg, var(--primary), var(--secondary));
}

@keyframes swipePulse {
  0%, 100% { transform: translateX(0); opacity: 0.8; }
  50% { transform: translateX(4px); opacity: 1; }
}

.info-card {
  cursor: pointer;
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.28s ease, border-color 0.28s ease;
}

.info-card:hover {
  transform: translateY(-8px) scale(1.012);
  border-color: rgba(216, 27, 44, 0.36);
  box-shadow: 0 24px 42px rgba(24, 16, 16, 0.12);
}

.info-section .feature-grid,
.team-grid,
.timeline-grid {
  display: grid;
  gap: 22px;
}

.event-grid {
  display: grid;
  grid-template-columns: repeat(3, minmax(0, 1fr));
  gap: 22px;
}

.event-card {
  padding: 22px;
  border-radius: var(--radius);
  background: linear-gradient(180deg, rgba(20,16,16,0.8), rgba(12, 10, 10, 0.76));
  border: 1px solid rgba(255,255,255,0.08);
  box-shadow: 0 18px 40px rgba(0,0,0,0.18);
  transition: transform 0.28s cubic-bezier(0.22, 1, 0.36, 1), box-shadow 0.28s ease, border-color 0.28s ease;
}

.event-card:hover {
  transform: translateY(-6px);
  border-color: rgba(216, 27, 44, 0.34);
  box-shadow: 0 22px 42px rgba(0, 0, 0, 0.2);
}

.latest-update-card {
  position: relative;
  margin-bottom: 22px;
  border-color: rgba(52, 211, 153, 0.38);
  background: linear-gradient(135deg, rgba(16, 185, 129, 0.16), rgba(20, 16, 16, 0.82) 48%);
  box-shadow: 0 18px 46px rgba(16, 185, 129, 0.12);
  overflow: hidden;
}

.latest-update-card:hover {
  border-color: rgba(52, 211, 153, 0.62);
  box-shadow: 0 22px 52px rgba(16, 185, 129, 0.2);
}

.announcement-card {
  cursor: pointer;
}

.announcement-card:focus-visible {
  outline: 2px solid #34d399;
  outline-offset: 4px;
}

.announcement-card h3 {
  font-size: clamp(2rem, 5vw, 3rem);
  line-height: 1.05;
}

.announcement-poster-wrap {
  position: relative;
  float: right;
  width: 150px;
  height: 110px;
  margin: 0 0 12px 22px;
  overflow: hidden;
  border: 1px solid rgba(52, 211, 153, 0.35);
  border-radius: 14px;
  background: rgba(16, 185, 129, 0.1);
}

.announcement-poster,
.announcement-no-image {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
}

.announcement-poster {
  object-fit: cover;
  opacity: 0;
  transform: scale(1.08);
  transition: opacity 0.35s ease, transform 0.35s ease;
}

.announcement-poster.has-image + .announcement-no-image {
  display: none;
}

.announcement-poster.has-image {
  opacity: 0.82;
}

.announcement-card:hover .announcement-poster.has-image,
.announcement-card:focus-visible .announcement-poster.has-image {
  opacity: 1;
  transform: scale(1);
}

.announcement-no-image {
  display: grid;
  place-items: center;
  padding: 12px;
  color: #a7f3d0;
  font-size: 0.68rem;
  text-align: center;
  text-transform: uppercase;
  letter-spacing: 0.1em;
}

.announcement-meta {
  display: flex;
  flex-wrap: wrap;
  gap: 8px 18px;
  margin-top: 14px;
  color: #a7f3d0;
  font-size: 0.78rem;
}

.latest-update-label {
  display: inline-flex;
  align-items: center;
  gap: 9px;
  color: #a7f3d0;
  font-size: 0.7rem;
  font-weight: 700;
  letter-spacing: 0.15em;
  text-transform: uppercase;
}

.latest-update-dot {
  width: 9px;
  height: 9px;
  border-radius: 50%;
  background: #34d399;
  box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.55), 0 0 16px rgba(52, 211, 153, 0.9);
  animation: latestUpdateBreath 1.8s ease-in-out infinite;
}

@keyframes latestUpdateBreath {
  0%, 100% { transform: scale(1); box-shadow: 0 0 0 0 rgba(52, 211, 153, 0.35), 0 0 16px rgba(52, 211, 153, 0.72); }
  50% { transform: scale(1.18); box-shadow: 0 0 0 7px rgba(52, 211, 153, 0), 0 0 24px rgba(52, 211, 153, 1); }
}

.event-card .small-label {
  color: var(--secondary);
  letter-spacing: 0.15em;
  text-transform: uppercase;
  font-size: 0.7rem;
}

.event-card h3 {
  margin: 18px 0 10px;
  color: var(--text);
  font-size: clamp(1.7rem, 3vw, 2.1rem);
}

.event-card p {
  margin: 0;
  color: var(--muted);
  line-height: 1.7;
}

.event-card .meta-row {
  margin-top: 18px;
  display: flex;
  justify-content: space-between;
  align-items: center;
  color: var(--muted);
  font-size: 0.82rem;
}

.event-card .status {
  display: inline-flex;
  align-items: center;
  gap: 8px;
  color: var(--text);
}

.event-card .status::before {
  content: "";
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: var(--green);
  box-shadow: 0 0 16px rgba(25, 183, 255, 0.8);
}

.team-header {
  text-align: center;
  max-width: 840px;
  margin: 0 auto 36px;
}

.team-header h2 {
  margin: 0;
  font-size: clamp(2.8rem, 5vw, 4rem);
  letter-spacing: -0.06em;
  color: var(--text);
}

.team-header p:last-child {
  max-width: 760px;
  margin: 18px auto 0;
  color: var(--muted);
  line-height: 1.8;
}

.team-grid {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}

.member-card {
  display: flex;
  align-items: center;
  gap: 16px;
  min-height: 118px;
  padding: 20px 22px;
  border-radius: var(--radius);
}

.member-avatar {
  width: 62px;
  height: 62px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-size: 0.9rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  color: #fff;
  background: linear-gradient(135deg, rgba(255, 176, 103, 0.8), rgba(216, 27, 44, 0.72));
}

.member-meta {
  display: flex;
  flex-direction: column;
  gap: 4px;
}

.member-meta h3 {
  margin: 0;
  font-size: clamp(1.08rem, 2vw, 1.55rem);
  font-weight: 600;
  color: var(--text);
}

.member-meta span {
  color: var(--muted);
}

.support-section {
  padding-bottom: 36px;
}

.centered {
  text-align: center;
}

.support-guide {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.support-step {
  padding: 24px 22px;
  border-radius: 28px;
}

.step-badge {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  font-size: 0.7rem;
  font-weight: 700;
  color: var(--text);
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
}

.support-step h3 {
  margin: 18px 0 12px;
  font-size: 1.5rem;
  color: var(--text);
}

.discord-channel-link {
  display: inline-flex;
  align-items: center;
  gap: 2px;
  padding: 4px 10px;
  margin: 0 4px;
  border-radius: 999px;
  background: rgba(88, 101, 242, 0.12);
  border: 1px solid rgba(88, 101, 242, 0.25);
  color: #b9c4ff;
  text-decoration: none;
  font-weight: 700;
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}

.discord-channel-link:hover {
  transform: translateY(-1px);
  box-shadow: 0 10px 18px rgba(88, 101, 242, 0.16);
  border-color: rgba(88, 101, 242, 0.42);
}

.discord-channel-hash {
  opacity: 0.9;
  font-weight: 800;
}

.support-step p {
  margin: 0;
  color: var(--muted);
  line-height: 1.8;
}

.support-visual {
  min-height: 220px;
  margin-top: 22px;
  border-radius: 18px;
  border: 1px solid rgba(255,255,255,0.08);
  display: flex;
  align-items: end;
  justify-content: center;
  padding: 18px;
  color: rgba(255,255,255,0.9);
  font-size: 0.74rem;
  letter-spacing: 0.14em;
  text-transform: uppercase;
}

.support-channel {
  background: linear-gradient(135deg, rgba(75, 71, 74, 0.86), rgba(31, 24, 26, 0.94));
}

.support-ticket {
  background: linear-gradient(135deg, rgba(106, 78, 76, 0.78), rgba(30, 24, 28, 0.88));
}

.site-footer {
  width: min(1200px, calc(100% - 32px));
  margin: 0 auto 30px;
  padding: 18px 0 6px;
}

.footer-wrap {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 18px;
  padding: 18px 20px;
  border-radius: 28px;
}

.footer-brand {
  display: flex;
  align-items: center;
  gap: 12px;
}

.footer-logo {
  width: 38px;
  height: 38px;
}

.footer-kicker {
  margin: 0;
  font-size: 0.72rem;
  letter-spacing: 0.16em;
  text-transform: uppercase;
  color: #f7d2d6;
}

.footer-sub {
  margin: 4px 0 0;
  color: var(--muted);
  font-size: 0.8rem;
}

.social-links {
  display: flex;
  align-items: center;
  gap: 12px;
}

.social-link {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  border: 1px solid rgba(255,255,255,0.1);
  background: rgba(255,255,255,0.02);
  color: var(--text);
  text-decoration: none;
  transition: transform 0.2s ease, border-color 0.2s ease;
}

.social-link:hover {
  transform: translateY(-2px) scale(1.04);
  border-color: rgba(255, 61, 77, 0.5);
}

.social-link svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

.detail-modal {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  opacity: 0;
  visibility: hidden;
  transition: opacity 0.25s ease, visibility 0.25s ease;
  z-index: 110;
}

.detail-modal.open {
  opacity: 1;
  visibility: visible;
}

.detail-modal-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(11, 8, 8, 0.55);
  backdrop-filter: blur(10px);
}

.detail-modal-panel {
  position: relative;
  z-index: 1;
  width: min(440px, calc(100% - 28px));
  padding: 26px 22px 22px;
  border-radius: 28px;
  background: linear-gradient(180deg, rgba(255,255,255,0.96), rgba(249, 242, 239, 0.97));
  border: 1px solid rgba(72, 38, 38, 0.08);
  box-shadow: 0 32px 80px rgba(18, 10, 10, 0.18);
  transform: translateY(18px) scale(0.96);
  transition: transform 0.25s ease;
}

.detail-modal.open .detail-modal-panel {
  transform: translateY(0) scale(1);
}

body[data-theme="dark"] .detail-modal-panel {
  background: linear-gradient(180deg, rgba(18, 14, 14, 0.98), rgba(25, 18, 18, 0.96));
  border-color: rgba(255,255,255,0.08);
}

.modal-close {
  position: absolute;
  top: 12px;
  right: 12px;
  width: 38px;
  height: 38px;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  color: var(--text);
  font-size: 1.6rem;
  cursor: pointer;
}

.modal-content {
  display: grid;
  gap: 14px;
}

.modal-badge {
  display: inline-flex;
  align-items: center;
  width: fit-content;
  padding: 7px 10px;
  border-radius: 999px;
  background: rgba(216, 27, 44, 0.08);
  border: 1px solid rgba(216, 27, 44, 0.2);
  color: var(--primary);
  letter-spacing: 0.14em;
  text-transform: uppercase;
  font-size: 0.68rem;
  font-weight: 700;
}

.modal-content h3 {
  margin: 0;
  font-size: clamp(1.8rem, 5vw, 2.4rem);
  letter-spacing: -0.05em;
}

.modal-content p {
  margin: 0;
  color: var(--muted);
  line-height: 1.75;
}

.modal-socials {
  display: flex;
  align-items: center;
  gap: 12px;
  margin-top: 4px;
}

.modal-socials a {
  width: 42px;
  height: 42px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255,255,255,0.04);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text);
}

.modal-socials svg {
  width: 18px;
  height: 18px;
  fill: currentColor;
}

.modal-cta {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  min-height: 48px;
  margin-top: 12px;
  padding: 0 18px;
  border-radius: 999px;
  text-decoration: none;
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  font-weight: 700;
}

.announcement-modal-badge,
.announcement-join {
  background: linear-gradient(135deg, #059669, #10b981);
}

.announcement-modal-details {
  display: grid;
  grid-template-columns: auto 1fr;
  gap: 8px 14px;
  padding: 14px;
  border: 1px solid rgba(52, 211, 153, 0.2);
  border-radius: 14px;
  background: rgba(16, 185, 129, 0.08);
}

.announcement-modal-details strong {
  color: #a7f3d0;
}

.announcement-modal-poster,
.announcement-modal-no-image {
  width: 100%;
  max-height: 280px;
  min-height: 120px;
  object-fit: cover;
  border-radius: 16px;
  border: 1px solid rgba(52, 211, 153, 0.3);
}

.announcement-modal-no-image {
  display: grid;
  place-items: center;
  color: #a7f3d0;
  background: rgba(16, 185, 129, 0.08);
}

.info-tip {
  position: fixed;
  left: 50%;
  bottom: 34px;
  transform: translateX(-50%);
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 12px 16px;
  border-radius: 999px;
  background: rgba(17, 14, 14, 0.88);
  border: 1px solid rgba(255,255,255,0.08);
  color: var(--text);
  box-shadow: 0 18px 42px rgba(0, 0, 0, 0.18);
  z-index: 100;
  opacity: 1;
  transition: opacity 0.25s ease, transform 0.25s ease;
}

body[data-theme="light"] .info-tip {
  background: rgba(255, 255, 255, 0.92);
}

.info-tip.hidden {
  opacity: 0;
  visibility: hidden;
  transform: translateX(-50%) translateY(10px);
}

.tip-close {
  width: 24px;
  height: 24px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgba(255,255,255,0.08);
  color: var(--text);
  cursor: pointer;
  font-size: 1.1rem;
}

.scroll-top {
  position: fixed;
  right: 26px;
  bottom: 26px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  display: grid;
  place-items: center;
  background: linear-gradient(135deg, var(--primary-strong), var(--primary));
  color: #fff;
  box-shadow: 0 18px 32px rgba(216, 27, 44, 0.26);
  opacity: 0;
  transform: translateY(18px) scale(0.85);
  pointer-events: none;
  transition: opacity 0.3s ease, transform 0.3s ease;
  z-index: 50;
}

.scroll-top.hidden {
  opacity: 0;
  visibility: hidden;
  pointer-events: none;
  transform: translateY(18px) scale(0.85);
}

.scroll-top.visible {
  opacity: 1;
  transform: translateY(0) scale(1);
  pointer-events: auto;
}

.reveal {
  opacity: 0;
  transform: translateY(28px);
  transition: opacity 0.8s cubic-bezier(0.22, 1, 0.36, 1), transform 0.8s cubic-bezier(0.22, 1, 0.36, 1);
}

.reveal.visible {
  opacity: 1;
  transform: translateY(0);
}

@keyframes drift {
  0% { transform: translate3d(0, 0, 0) scale(1); }
  100% { transform: translate3d(24px, 30px, 0) scale(1.08); }
}

@keyframes floatCard {
  0% { transform: rotate(8deg) translateY(0); }
  100% { transform: rotate(8deg) translateY(-12px); }
}

@keyframes pulse {
  0%, 100% { opacity: 1; transform: scale(1); }
  50% { opacity: 0.8; transform: scale(1.09); }
}

@media (max-width: 980px) {
  .top-nav {
    display: none;
  }

  .menu-toggle {
    display: inline-flex;
  }

  .hero,
  .featured-slide,
  .support-guide {
    grid-template-columns: 1fr;
  }

  .featured-carousel,
  .gallery-shell {
    gap: 12px;
  }

  .hero-visual {
    width: 100%;
    margin-left: 0;
  }

  .feature-grid,
  .study-grid,
  .team-grid,
  .event-grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
  }

  .split-header,
  .gallery-header,
  .footer-wrap {
    flex-direction: column;
    align-items: flex-start;
  }
}

@media (max-width: 640px) {
  .site-header {
    width: min(100% - 18px, 1200px);
    margin-top: 12px;
    padding: 12px 14px;
  }

  .hero {
    gap: 28px;
    padding-top: 18px;
  }

  .live-pill {
    width: 100%;
    justify-content: center;
  }

  .hero-visual {
    min-height: 420px;
  }

  .visual-card {
    width: 100%;
    max-width: 100%;
  }

  .main-card {
    min-height: 250px;
  }

  .floating-card {
    right: 10px;
    width: min(235px, 64%);
    padding: 18px;
    bottom: 20px;
  }

  .intro-mode-picker {
    width: 100%;
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 10px;
  }

  .theme-choice-btn {
    min-width: 0;
    width: 100%;
    font-size: 0.8rem;
    padding: 0.9rem 0.7rem;
  }

  .brand-name {
    font-size: 0.72rem;
  }

  .section-shell {
    width: min(calc(100% - 20px), 1200px);
    padding-top: 68px;
    padding-bottom: 68px;
  }

  .hero {
    min-height: auto;
    gap: 22px;
    padding-top: 30px;
  }

  .hero-copy {
    max-width: 100%;
  }

  .hero-visual {
    width: 100%;
    min-height: auto;
    display: flex;
    flex-direction: column;
    gap: 14px;
  }

  .visual-card {
    width: 100%;
    max-width: 100%;
  }

  .hero h1 {
    font-size: clamp(2.9rem, 14vw, 4.2rem);
    line-height: 0.92;
    letter-spacing: -0.075em;
    margin-top: 18px;
  }

  .subtext {
    font-size: 1rem;
    line-height: 1.7;
    margin-top: 16px;
  }

  .hero-actions {
    flex-direction: column;
    align-items: stretch;
    margin-top: 22px;
    gap: 12px;
  }

  .hero-badges {
    margin-top: 18px;
    gap: 8px;
  }

  .hero-badges span {
    padding: 8px 12px;
  }

  .primary-cta,
  .secondary-cta {
    width: 100%;
  }

  .feature-grid,
  .study-grid,
  .team-grid,
  .event-grid,
  .support-guide {
    grid-template-columns: 1fr;
  }

  .member-card {
    min-height: 104px;
  }

  .main-card {
    transform: none;
  }

  .floating-card {
    position: relative;
    right: auto;
    bottom: auto;
    width: 100%;
    transform: none;
    margin-top: 0;
  }

  .featured-carousel,
  .gallery-shell {
    grid-template-columns: 1fr;
    gap: 12px;
  }

  .announcement-card {
    display: grid;
    grid-template-columns: 1fr;
    gap: 0;
  }

  .announcement-card .latest-update-label {
    order: 1;
  }

  .announcement-card h3 {
    order: 2;
    max-width: 100%;
    margin-top: 14px;
    font-size: clamp(1.8rem, 9vw, 2.6rem);
  }

  .announcement-card p {
    order: 4;
  }

  .announcement-card .announcement-meta {
    order: 3;
    margin-top: 10px;
  }

  .announcement-card .announcement-poster-wrap {
    order: 5;
    float: none;
    width: 100%;
    height: 190px;
    margin: 16px 0 0;
  }

  .announcement-card .meta-row {
    order: 6;
    margin-top: 14px;
  }

  .featured-copy {
    padding-right: 0;
  }

  .featured-slide,
  .study-card,
  .member-card,
  .event-card,
  .gallery-slide {
    border-radius: 22px;
  }

  .carousel-meta {
    padding: 0 4px;
  }

  .site-header,
  .section-shell,
  .featured-slide,
  .study-copy,
  .member-card,
  .event-card,
  .support-card {
    scroll-margin-top: 80px;
  }

  .info-tip {
    left: 12px;
    right: 12px;
    bottom: 18px;
    transform: none;
    width: auto;
    justify-content: space-between;
  }

  .info-tip.hidden {
    transform: translateY(10px);
  }

  .theme-toggle {
    width: 42px;
    height: 42px;
  }

  .theme-toggle__icon svg {
    width: 18px;
    height: 18px;
  }

  .carousel-meta {
    gap: 8px;
  }

  .swipe-hint {
    font-size: 0.64rem;
    letter-spacing: 0.08em;
  }

  .swipe-hint__dot {
    width: 8px;
    height: 8px;
  }

  .carousel-dot {
    transition-duration: 0.15s;
  }

  .featured-track,
  .gallery-track,
  .info-card,
  .gallery-slide,
  .blur-one,
  .blur-two,
  .floating-card,
  .site-header,
  .theme-toggle,
  .menu-toggle,
  .primary-cta,
  .secondary-cta,
  .live-dot,
  #memberCount {
    transition-duration: 0.2s !important;
    animation: none !important;
  }

  .main-card,
  .floating-card {
    animation: none !important;
  }

  .info-card:hover,
  .gallery-slide:hover,
  .gallery-slide:hover .gallery-image {
    transform: none;
    box-shadow: none;
  }
}

@media (prefers-reduced-motion: reduce) {
  html { scroll-behavior: auto; }
  *, *::before, *::after {
    animation: none !important;
    transition: none !important;
  }
  .reveal { opacity: 1; transform: none; }
}

