import 'dotenv/config';
import express from 'express';
import { randomUUID } from 'node:crypto';
import fs from 'node:fs/promises';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const app = express();
const port = Number(process.env.PORT || 3001);
const __filename = fileURLToPath(import.meta.url);
const __dirname = path.dirname(__filename);
const dataFile = path.join(__dirname, 'updates.json');
const memberFile = path.join(__dirname, 'member-count.json');
const serverStatsFile = path.join(__dirname, 'server-stats.json');
const currentEventFile = path.join(__dirname, 'current-event.json');

app.use(express.json({ limit: '5mb' }));

app.use((req, res, next) => {
  const origin = req.headers.origin;
  const allowedOrigins = (process.env.ALLOWED_ORIGINS || '').split(',').filter(Boolean);

  if (!origin || allowedOrigins.includes(origin)) {
    res.header('Access-Control-Allow-Origin', origin || '*');
    res.header('Access-Control-Allow-Headers', 'Content-Type, x-api-key');
    res.header('Access-Control-Allow-Methods', 'GET, POST, OPTIONS');
  }

  if (req.method === 'OPTIONS') return res.sendStatus(200);
  next();
});

const readJson = async (file) => {
  try {
    const raw = await fs.readFile(file, 'utf8');
    return JSON.parse(raw);
  } catch {
    return [];
  }
};

const writeJson = async (file, data) => {
  await fs.writeFile(file, JSON.stringify(data, null, 2));
};

const getMemberCount = async () => {
  try {
    const raw = await fs.readFile(memberFile, 'utf8');
    const payload = JSON.parse(raw);
    return Number(payload.memberCount || 0);
  } catch {
    return 0;
  }
};

const getServerStats = async () => {
  const stats = await readJson(serverStatsFile);
  return Array.isArray(stats) ? {} : stats;
};

app.get('/api/health', (req, res) => {
  res.json({ ok: true, service: 'cfc-discord-bot' });
});

app.get('/api/site-data', async (req, res) => {
  const updates = await readJson(dataFile);
  const memberCount = await getMemberCount();
  const currentEvent = await readJson(currentEventFile);
  const serverStats = await getServerStats();

  res.json({
    memberCount,
    updates,
    currentEvent,
    serverStats,
    syncedAt: new Date().toISOString()
  });
});

app.post('/api/server-stats', async (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ ok: false, message: 'Invalid API key' });
  }

  const { memberCount, voiceChannels, chatChannels, updatedAt } = req.body || {};
  const values = [memberCount, voiceChannels, chatChannels].map(Number);

  if (values.some((value) => !Number.isInteger(value) || value < 0)) {
    return res.status(400).json({ ok: false, message: 'Invalid server statistics' });
  }

  const serverStats = {
    memberCount: values[0],
    voiceChannels: values[1],
    chatChannels: values[2],
    updatedAt: updatedAt || new Date().toISOString()
  };

  await writeJson(serverStatsFile, serverStats);
  res.json({ ok: true, serverStats });
});

app.post('/api/current-event', async (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ ok: false, message: 'Invalid API key' });
  }

  const { title, progress, updatedAt } = req.body || {};
  const numericProgress = Number(progress);

  if (!title || !Number.isInteger(numericProgress) || numericProgress < 0 || numericProgress > 100) {
    return res.status(400).json({ ok: false, message: 'Title and progress from 0 to 100 are required' });
  }

  const currentEvent = {
    title,
    progress: numericProgress,
    updatedAt: updatedAt || new Date().toISOString()
  };

  await writeJson(currentEventFile, currentEvent);
  res.json({ ok: true, currentEvent });
});

app.post('/api/member-count', async (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ ok: false, message: 'Invalid API key' });
  }

  const { memberCount, updatedAt } = req.body || {};

  if (!memberCount && Number(memberCount) !== 0) {
    return res.status(400).json({ ok: false, message: 'Invalid member count' });
  }

  const payload = {
    memberCount: Number(memberCount),
    updatedAt: updatedAt || new Date().toISOString()
  };

  await writeJson(memberFile, payload);
  res.json({ ok: true, payload });
});

app.post('/api/update', async (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ ok: false, message: 'Invalid API key' });
  }

  const { newEvent, title, body, date, time, inviteLink, poster, submittedBy, submittedAt } = req.body || {};

  if (!newEvent || !title || !body || !date || !time || !inviteLink) {
    return res.status(400).json({ ok: false, message: 'Missing required announcement fields' });
  }

  const record = {
    id: randomUUID(),
    newEvent,
    title,
    body,
    poster: poster || null,
    date,
    time,
    inviteLink,
    submittedBy: submittedBy || 'Discord bot',
    submittedAt: submittedAt || new Date().toISOString()
  };

  const all = await readJson(dataFile);
  all.unshift(record);
  await writeJson(dataFile, all);

  res.json({ ok: true, record });
});

app.post('/api/clear-updates', async (req, res) => {
  const apiKey = req.headers['x-api-key'];

  if (apiKey !== process.env.API_KEY) {
    return res.status(401).json({ ok: false, message: 'Invalid API key' });
  }

  await writeJson(dataFile, []);
  res.json({ ok: true, updates: [] });
});

app.get('/api/updates', async (req, res) => {
  const updates = await readJson(dataFile);
  res.json(updates);
});

app.listen(port, () => {
  console.log(`Bot API running on http://localhost:${port}`);
});

import 'dotenv/config';
import { Client, GatewayIntentBits, InteractionType, MessageFlags } from 'discord.js';

const client = new Client({
  intents: [GatewayIntentBits.Guilds, GatewayIntentBits.GuildMessages, GatewayIntentBits.MessageContent]
});

const allowedRoleId = process.env.ALLOWED_ROLE_ID;
const apiUrl = `http://localhost:${process.env.PORT || 3001}`;

const canManageBot = (member, userId) => (
  !allowedRoleId || member?.roles?.cache?.has(allowedRoleId) || userId === process.env.OWNER_ID
);

const isUnavailableInteraction = (error) => error?.code === 10062 || error?.code === 40060;

const helpMessage = `Commands:\nCCforceupdate or /forceupdate - sync member and channel totals.\n/update current_event - update the current event card.\n/update announcement - publish an event announcement.\n/update no_announcements - clear announcements and show No active events.\nCChelp or /help - show this help.\n\nAllowed role: ${allowedRoleId || 'any server member'} (the owner is also allowed).`;

const sendInteractionError = async (interaction, content) => {
  if (interaction.deferred) {
    try {
      await interaction.editReply(content);
    } catch (error) {
      if (!isUnavailableInteraction(error)) console.error('Failed to edit interaction error:', error);
    }
    return;
  }

  if (!interaction.replied) {
    try {
      await interaction.reply({ content, flags: MessageFlags.Ephemeral });
    } catch (error) {
      if (!isUnavailableInteraction(error)) console.error('Failed to reply to interaction error:', error);
    }
  }
};

const getGuildMemberCount = async () => {
  try {
    const guild = await client.guilds.fetch(process.env.GUILD_ID);
    return guild.memberCount ?? 0;
  } catch (error) {
    console.error('Failed to fetch guild member count:', error);
    return 0;
  }
};

const syncMemberCount = async () => {
  const count = await getGuildMemberCount();

  try {
    const response = await fetch(`${apiUrl}/api/member-count`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.API_KEY || 'change-me' },
      body: JSON.stringify({ memberCount: count, updatedAt: new Date().toISOString() })
    });
    return response.ok;
  } catch (error) {
    console.error('Failed to sync member count:', error);
    return false;
  }
};

const getServerStats = async () => {
  const guild = await client.guilds.fetch(process.env.GUILD_ID);
  const channels = await guild.channels.fetch();
  let voiceChannels = 0;
  let chatChannels = 0;

  for (const channel of channels.values()) {
    if (channel?.type === 2) voiceChannels += 1;
    if (channel?.type === 0 || channel?.type === 5 || channel?.type === 15) chatChannels += 1;
  }

  return { memberCount: guild.memberCount ?? 0, voiceChannels, chatChannels };
};

const syncServerStats = async () => {
  try {
    const stats = await getServerStats();
    const response = await fetch(`${apiUrl}/api/server-stats`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.API_KEY || 'change-me' },
      body: JSON.stringify({ ...stats, updatedAt: new Date().toISOString() })
    });
    return response.ok;
  } catch (error) {
    console.error('Failed to sync server stats:', error);
    return false;
  }
};

const forceUpdate = async () => {
  const synced = await syncServerStats();
  return { synced, stats: synced ? await getServerStats() : null };
};

client.once('ready', () => {
  console.log(`Logged in as ${client.user.tag}`);
  syncMemberCount();
  syncServerStats();
  setInterval(syncMemberCount, 30000);
  setInterval(syncServerStats, 30000);
});

client.on('messageCreate', async (message) => {
  if (message.author.bot) return;

  const command = message.content.trim().toLowerCase();
  if (command === 'cchelp' || command === 'cc help') {
    await message.reply(helpMessage);
    return;
  }
  if (command !== 'ccforceupdate' && command !== 'cc forceupdate') return;

  if (!canManageBot(message.member, message.author.id)) {
    await message.reply('You do not have permission to force a member count update.');
    return;
  }

  const { synced, stats } = await forceUpdate();
  const count = stats?.memberCount ?? await getGuildMemberCount();
  await message.reply(synced
    ? `Member count updated: **${count.toLocaleString()}**`
    : 'Could not reach the website API. The member count was not updated.');
});

client.on('interactionCreate', async (interaction) => {
  if (interaction.type !== InteractionType.ApplicationCommand) return;

  if (interaction.commandName === 'forceupdate') {
    if (!canManageBot(interaction.member, interaction.user.id)) {
      await interaction.reply({
        content: 'You do not have permission to force a member count update.',
        flags: MessageFlags.Ephemeral
      });
      return;
    }

    try {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral });
      const { synced, stats } = await forceUpdate();
      const count = stats?.memberCount ?? await getGuildMemberCount();
      await interaction.editReply(synced
        ? `Member count updated: **${count.toLocaleString()}**`
        : 'Could not reach the website API. The member count was not updated.');
    } catch (error) {
      if (isUnavailableInteraction(error)) return;
      console.error(error);
      await sendInteractionError(interaction, 'Could not complete the member count update.');
    }
    return;
  }

  if (interaction.commandName === 'help') {
    await interaction.reply({ content: helpMessage, flags: MessageFlags.Ephemeral });
    return;
  }

  if (interaction.commandName !== 'update') return;

  if (!canManageBot(interaction.member, interaction.user.id)) {
    await interaction.reply({
      content: 'You do not have permission to use this command.',
      flags: MessageFlags.Ephemeral
    });
    return;
  }

  const subcommand = interaction.options.getSubcommand();

  if (subcommand === 'no_announcements') {
    try {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral });
      const response = await fetch(`${apiUrl}/api/clear-updates`, {
        method: 'POST',
        headers: { 'x-api-key': process.env.API_KEY || 'change-me' }
      });
      if (!response.ok) throw new Error('Failed to clear announcements');
      await interaction.editReply('Announcements cleared. The website now shows No active events with null date and time.');
    } catch (error) {
      if (isUnavailableInteraction(error)) return;
      console.error(error);
      await sendInteractionError(interaction, 'Failed to clear announcements.');
    }
    return;
  }

  if (subcommand === 'current_event') {
    const title = interaction.options.getString('title', true);
    const progress = interaction.options.getInteger('progress', true);

    try {
      await interaction.deferReply({ flags: MessageFlags.Ephemeral });
      const response = await fetch(`${apiUrl}/api/current-event`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.API_KEY || 'change-me' },
        body: JSON.stringify({ title, progress, updatedAt: new Date().toISOString() })
      });

      if (!response.ok) throw new Error('Failed to save current event');
      await interaction.editReply(`Current event updated: **${title}** (${progress}%).`);
    } catch (error) {
      if (isUnavailableInteraction(error)) return;
      console.error(error);
      await sendInteractionError(interaction, 'Failed to update the current event card.');
    }
    return;
  }

  const newEvent = interaction.options.getString('new_event', true);
  const title = interaction.options.getString('title', true);
  const body = interaction.options.getString('body', true);
  const date = interaction.options.getString('date', true);
  const time = interaction.options.getString('time', true);
  const inviteLink = interaction.options.getString('invite_link', true);
  const poster = interaction.options.getAttachment('poster');
  if (!/^\d{4}-\d{2}-\d{2}$/.test(date) || !/^\d{2}:\d{2}(\s+[A-Za-z]{2,5})?$/.test(time)) {
    await interaction.reply({
      content: 'Use date YYYY-MM-DD and time HH:mm, optionally followed by a timezone such as UTC.',
      flags: MessageFlags.Ephemeral
    });
    return;
  }
  const payload = {
    newEvent,
    title,
    body,
    date,
    time,
    inviteLink,
    poster: poster?.url || null,
    submittedBy: interaction.user.tag,
    submittedAt: new Date().toISOString()
  };

  try {
    await interaction.deferReply({ flags: MessageFlags.Ephemeral });
    const response = await fetch(`${apiUrl}/api/update`, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-api-key': process.env.API_KEY || 'change-me' },
      body: JSON.stringify(payload)
    });

    if (!response.ok) throw new Error('Failed to save update');
    await interaction.editReply(`Update submitted for **${newEvent}**.`);
  } catch (error) {
    if (isUnavailableInteraction(error)) return;
    console.error(error);
    await sendInteractionError(interaction, 'Failed to submit the update.');
  }
});

client.login(process.env.DISCORD_TOKEN);

